import {Tab, Tabs} from '@jetbrains/ring-ui-built/components/tabs/tabs'
import Toggle, {Size} from '@jetbrains/ring-ui-built/components/toggle/toggle'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {useCallback, useEffect, useMemo} from 'react'
import type {EntryPointProps} from 'react-relay'

import {useQueryParamState, useSyncedBooleanQueryParam} from '../../../hooks/routes'
import useDocumentTitle from '../../../hooks/useDocumentTitle'
import {useSetUserProperty} from '../../../hooks/useSetUserProperty'
import {useUserProperty} from '../../../hooks/useUserProperty'
import {UserProperties} from '../../../utils/userProperties'
import PageTitle from '../../common/PageTitle/PageTitle'

import ServerHealthTab from './ServerHealthTab/ServerHealthTab'
import {useServerHealthItems} from './ServerHealthTab/ServerHealthTab.hooks'

import styles from './NotificationsPage.module.css'

enum NotificationsPageTabs {
  ALL = 'all',
  SERVER_HEALTH = 'server-health',
}

export default function NotificationsPage(_: EntryPointProps<{}, {}, {}, {}>) {
  useDocumentTitle(`Notifications - TeamCity`)
  const [unreadsOnly, setUnreadsOnly] = useSyncedBooleanQueryParam({
    param: 'unreadsOnly',
    userProperty: UserProperties.SHOW_ONLY_UNREAD_NOTIFICATIONS,
  })
  const [tab, setTab] = useQueryParamState('tab')
  const {serverHealthItems, serverHealthItemsLoaded, serverHealthLoader} = useServerHealthItems()
  const readNotificationsString = useUserProperty(UserProperties.READ_NOTIFICATIONS)
  const readNotifications = useMemo(
    () => readNotificationsString?.split(',') ?? [],
    [readNotificationsString],
  )
  const unreadServerHealthItems = serverHealthItems.filter(
    item => !readNotifications.includes(item.identity),
  )
  const setUserProperty = useSetUserProperty()
  const setReadNotifications = useCallback(
    (produce: (prevIds: string[]) => string[]) => {
      const newReadNotificationsString = produce(readNotifications).sort().join(',')
      if (newReadNotificationsString !== readNotificationsString) {
        setUserProperty(UserProperties.READ_NOTIFICATIONS, newReadNotificationsString)
      }
    },
    [readNotifications, readNotificationsString, setUserProperty],
  )
  useEffect(() => {
    if (serverHealthItemsLoaded) {
      setReadNotifications(prevIds =>
        prevIds.filter(id => serverHealthItems.some(item => item.identity === id)),
      )
    }
  }, [readNotifications, serverHealthItems, serverHealthItemsLoaded, setReadNotifications])

  return (
    <>
      <div className={styles.header}>
        <PageTitle>{'Notifications'}</PageTitle>
        <div className={styles.controls}>
          <Toggle
            size={Size.Size14}
            leftLabel="Unreads"
            checked={unreadsOnly}
            onChange={e => setUnreadsOnly(e.currentTarget.checked)}
          />
        </div>
      </div>
      <Tabs selected={tab ?? NotificationsPageTabs.SERVER_HEALTH} onSelect={setTab}>
        {/*<Tab id={NotificationsPageTabs.ALL} title="All" />*/}
        <Tab
          id={NotificationsPageTabs.SERVER_HEALTH}
          title={
            <>
              {serverHealthItems.some(item => item.severity === 'Error') && (
                <SvgIcon icon="exception-12px" className={styles.errorIcon} />
              )}
              {'Server Health'}
              {unreadServerHealthItems.length > 0 && (
                <span className={styles.counter}>{unreadServerHealthItems.length}</span>
              )}
            </>
          }
        >
          <ServerHealthTab
            serverHealthItems={serverHealthItems}
            serverHealthItemsLoaded={serverHealthItemsLoaded}
            unreadServerHealthItems={unreadServerHealthItems}
            unreadsOnly={unreadsOnly}
            setReadNotifications={setReadNotifications}
          />
        </Tab>
      </Tabs>
      {serverHealthLoader}
    </>
  )
}
export type NotificationsPageComponent = typeof NotificationsPage
