import {H3, H4} from '@jetbrains/ring-ui-built/components/heading/heading'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import plur from 'plur'

import type {HealthItemOwnProps} from '../../../App/Header/HealthItem/HealthItem.types'
import Loader from '../../../common/Loader/Loader'
import Notification from '../Notification/Notification'

import styles from './ServerHealthTab.module.css'

type Props = {
  serverHealthItems: readonly HealthItemOwnProps[]
  serverHealthItemsLoaded: boolean
  unreadServerHealthItems: readonly HealthItemOwnProps[]
  unreadsOnly: boolean
  setReadNotifications: (produce: (prevIds: string[]) => string[]) => void
}

function ServerHealthTab({
  serverHealthItems,
  serverHealthItemsLoaded,
  unreadServerHealthItems,
  unreadsOnly,
  setReadNotifications,
}: Props) {
  const serverHealthItemsToShow = unreadsOnly ? unreadServerHealthItems : serverHealthItems
  const infoCount = serverHealthItems.filter(item => item.severity === 'Info').length
  const warningsCount = serverHealthItems.filter(item => item.severity === 'Warning').length
  const errorsCount = serverHealthItems.filter(item => item.severity === 'Error').length

  return serverHealthItemsLoaded ? (
    <>
      <div
        className={classNames(
          styles.report,
          errorsCount > 0
            ? styles.withErrors
            : warningsCount > 0
              ? styles.withWarnings
              : infoCount > 0
                ? styles.withInfo
                : styles.empty,
        )}
      >
        <H3 className={styles.reportHeading}>{'Server Health Report'}</H3>
        <div className={styles.reportColumns}>
          <div className={styles.reportColumn}>
            <H4 className={styles.reportColumnHeading}>{'CRITICAL'}</H4>
            <div className={styles.reportColumnCount}>
              {`${errorsCount} ${plur('issue', errorsCount)}`}
              {errorsCount > 0 && <SvgIcon icon="exception" className={styles.errorIcon} />}
            </div>
          </div>
          <div className={styles.reportColumn}>
            <H4 className={styles.reportColumnHeading}>{'WARNINGS'}</H4>
            <div className={styles.reportColumnCount}>
              {`${warningsCount} ${plur('issue', warningsCount)}`}
              {warningsCount > 0 && <SvgIcon icon="warning" className={styles.warningIcon} />}
            </div>
          </div>
          <div className={styles.reportColumn}>
            <H4 className={styles.reportColumnHeading}>{'RECOMMENDATIONS'}</H4>
            <div className={styles.reportColumnCount}>
              {`${infoCount} info`}
              {infoCount > 0 && <SvgIcon icon="info" className={styles.infoIcon} />}
            </div>
          </div>
        </div>
      </div>
      {serverHealthItemsToShow.length > 0 && (
        <div className={styles.notificationsHeaderWrapper}>
          <H4 className={styles.notificationsHeader}>{'CURRENT'}</H4>
          <Link
            disabled={unreadServerHealthItems.length === 0}
            className={styles.markAsRead}
            onClick={() =>
              setReadNotifications(prevIds => [
                ...prevIds,
                ...unreadServerHealthItems.map(item => item.identity),
              ])
            }
          >
            {'Mark all as read'}
          </Link>
        </div>
      )}
      <div className="globalWarningsWrapper-sakura">
        {serverHealthItems.map(item => {
          const unread = unreadServerHealthItems.includes(item)
          return (
            <Notification
              key={item.identity}
              unread={unread}
              item={item}
              setReadNotifications={setReadNotifications}
            />
          )
        })}
      </div>
    </>
  ) : (
    <Loader />
  )
}

export default ServerHealthTab
