import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {IconButton, SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'

import {useBooleanQueryParam} from '../../../../hooks/routes'
import {truthy} from '../../../../utils/guards'
import {hideHealthItem} from '../../../App/Header/HealthItem/HealthItem'
import HealthItem from '../../../App/Header/HealthItem/HealthItem.lazy'
import type {HealthItemOwnProps} from '../../../App/Header/HealthItem/HealthItem.types'
import PopupMenu from '../../../common/Popup/PopupMenu.lazy'

import styles from './Notification.module.css'

type Props = {
  item: HealthItemOwnProps
  unread: boolean
  setReadNotifications: (produce: (prevIds: string[]) => string[]) => void
}

function Notification({item, unread, setReadNotifications}: Props) {
  const unreadsOnly = useBooleanQueryParam('unreadsOnly')

  return (
    <div
      hidden={unreadsOnly && !unread}
      className={classNames(styles.notification, {
        [styles.unread]: unread,
      })}
    >
      <div
        className={classNames(
          styles.notificationIconWrapper,
          styles[`notificationIconWrapper${item.severity}`],
        )}
      >
        {unread && <div className={styles.unreadDot} />}
        <SvgIcon
          icon={
            item.severity === 'Error'
              ? 'exception-20px'
              : item.severity === 'Warning'
                ? 'warning-20px'
                : 'info-20px'
          }
          className={styles.notificationIcon}
        />
      </div>
      <div className={styles.notificationBodyWrapper}>
        <div className={styles.notificationTitle}>
          {item.severity === 'Error'
            ? 'Critical'
            : item.severity === 'Warning'
              ? 'Warning'
              : 'Recommendation'}
          <Dropdown anchor={<IconButton icon="more-options" />} className={styles.actions}>
            <PopupMenu
              closeOnSelect
              data={[
                {
                  label: unread ? 'Mark as read' : 'Mark as unread',
                  onClick: () =>
                    setReadNotifications(prevIds =>
                      unread
                        ? [...prevIds, item.identity]
                        : prevIds.filter(id => id !== item.identity),
                    ),
                },
                item.canHidePersonal && {
                  label: 'Hide for me',
                  onClick: () => hideHealthItem(item, false),
                },
                item.canHideGlobal && {
                  label: 'Hide for everyone',
                  onClick: () => hideHealthItem(item, true),
                },
              ].filter(truthy)}
            />
          </Dropdown>
        </div>
        <div className={styles.notificationBody}>
          <HealthItem
            {...item}
            inline
            truncate={false}
            parentSelector='[data-notifications-server-health="true"] '
          />
        </div>
      </div>
    </div>
  )
}

export default Notification
