import {useCallback, useState} from 'react'

import {BS} from '../../../../types/BS_types'
import {emptyArray} from '../../../../utils/empty'
import type {HealthItemOwnProps} from '../../../App/Header/HealthItem/HealthItem.types'
import InjectHtml from '../../../common/InjectHtml/InjectHtml'

export function useServerHealthItems() {
  const [serverHealthItemsLoaded, setServerHealthItemsLoaded] = useState(false)
  const [serverHealthItems, setServerHealthItems] =
    useState<readonly HealthItemOwnProps[]>(emptyArray)
  const handleServerHealthLoad = useCallback(() => {
    setServerHealthItems(BS.globalHealthItems ?? emptyArray)
    setServerHealthItemsLoaded(true)
    BS.globalHealthItems = emptyArray
  }, [])
  return {
    serverHealthItemsLoaded,
    serverHealthItems,
    serverHealthLoader: (
      <div hidden data-notifications-server-health="true">
        <InjectHtml
          path="admin/globalHealthStatusItems.html?skipRender=true"
          onLoad={handleServerHealthLoad}
        />
      </div>
    ),
  }
}
